begin;
insert into auth.users(id,email)values('91000000-0000-4000-8000-000000000001','origin-owner@example.invalid'),('91000000-0000-4000-8000-000000000002','origin-member@example.invalid');
insert into public.workspaces(id,name,slug)values('92000000-0000-4000-8000-000000000001','Origin Synthetic','origin-synthetic');
insert into public.workspace_members(workspace_id,user_id,role)values('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','owner'),('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000002','member');
insert into public.customers(id,workspace_id,account_kind,legal_name)values('93000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000001','legal_entity','Legacy Origin');
insert into public.team_invite_intents(id,workspace_id,email,role,created_by_user_id,created_at,expires_at)values('94000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000001','synthetic@example.invalid','member','91000000-0000-4000-8000-000000000001',statement_timestamp()-interval '8 days',statement_timestamp()-interval '1 day');
create function pg_temp.assert_o(ok boolean)returns void language plpgsql as $$begin if ok is not true then raise exception 'origin_assertion';end if;end$$;
create function pg_temp.deny_o(q text,c text)returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=c then return;end if;raise;end;raise exception 'expected_origin_denial';end$$;
set local role authenticated;select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_o(public.team_v1_member_invite_list('92000000-0000-4000-8000-000000000001','{}')->'items'->0->>'status'='expired');
select pg_temp.assert_o(public.team_v1_member_reissue_invite('92000000-0000-4000-8000-000000000001','{"command_id":"95000000-0000-4000-8000-000000000001","id":"94000000-0000-4000-8000-000000000001","expected_version":1}')->>'version'='2');
select pg_temp.assert_o(public.team_v1_member_reissue_invite('92000000-0000-4000-8000-000000000001','{"command_id":"95000000-0000-4000-8000-000000000001","id":"94000000-0000-4000-8000-000000000001","expected_version":1}')->>'version'='2');
select pg_temp.deny_o($q$select public.team_v1_member_reissue_invite('92000000-0000-4000-8000-000000000001','{"command_id":"95000000-0000-4000-8000-000000000002","id":"94000000-0000-4000-8000-000000000001","expected_version":1}')$q$,'40001');
select pg_temp.assert_o(public.provenance_v1_get('92000000-0000-4000-8000-000000000001','{"kind":"customer","id":"93000000-0000-4000-8000-000000000001"}')->>'confidence'='declared_legacy_manual');
do $$declare r jsonb;begin r:=public.product_v1_customer_create('92000000-0000-4000-8000-000000000001','{"command_id":"95000000-0000-4000-8000-000000000003","account_kind":"legal_entity","legal_name":"New Origin"}');perform pg_temp.assert_o(public.provenance_v1_get('92000000-0000-4000-8000-000000000001',jsonb_build_object('kind','customer','id',r->>'id'))->>'confidence'='verified_new_manual');end$$;
reset role;
select pg_temp.assert_o((select count(*)=1 from public.product_manual_origin_proofs));
select pg_temp.deny_o($q$update public.product_manual_origin_proofs set verified_at=statement_timestamp()$q$,'55000');
select pg_temp.assert_o((select count(*)=1 from public.product_audit_events where operation='member.reissue_invite'));
set local role authenticated;select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000002',true);
select pg_temp.deny_o($q$select public.team_v1_member_invite_list('92000000-0000-4000-8000-000000000001','{}')$q$,'42501');
select pg_temp.deny_o($q$select public.provenance_v1_get('92000000-0000-4000-8000-000000000001','{"kind":"customer","id":"93000000-0000-4000-8000-000000000001"}')$q$,'42501');
reset role;rollback;
